<details>
<summary>Complete public-SDK probe</summary>

```js
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import path from 'node:path';
import { Worker, isMainThread, parentPort, workerData } from 'node:worker_threads';
if (isMainThread) {
  const root = path.resolve(process.env.OPENCLAW_STATE_DIR);
  await fs.mkdir(root, { recursive: true });
  const worker = new Worker(new URL(import.meta.url), { workerData: { root, connection: process.env.READONLY_PROOF_CONNECTION } });
  try {
    const result = await new Promise((resolve, reject) => {
      worker.once('message', resolve); worker.once('error', reject);
      worker.once('exit', code => { if (code !== 0) reject(new Error('SDK worker exited '+code)); });
    });
    console.log(JSON.stringify(result));
  } finally { await worker.terminate(); }
} else {
  const sdk = import.meta.resolve('openclaw/plugin-sdk/database-engine-worker-runtime');
  assert(sdk.includes('/dist/'), 'Consumer must use the built public package export');
  const { openEngineStore, withEngineStoreAdmission } = await import('openclaw/plugin-sdk/database-engine-worker-runtime');
  const { openNodeSqliteDatabase, admitSqliteSchema } = await import('openclaw/plugin-sdk/sqlite-worker-runtime');
  const anchor = openNodeSqliteDatabase(path.join(workerData.root, 'anchor.sqlite'));
  const schema = { id: 'readonly_sdk_probe', version: 1, sqlite: '', postgres: 'CREATE TABLE items (id BIGINT PRIMARY KEY, value TEXT NOT NULL)' };
  const opened = [];
  const result = withEngineStoreAdmission(() => {
    const open = readOnly => {
      const db = openEngineStore({ anchor, schema, input: { connection: workerData.connection, schemaPrefix: 'readonly_sdk', ...(readOnly ? { readOnly: true } : {}) }, reusePostgresConnection: true,
        openSqlite() { throw new Error('Unexpected SQLite fallback'); }, prepareAnchor() {},
        inspectSqlite() { admitSqliteSchema(anchor); return { hasExistingData: false, hasEngineAnchor: anchor.prepare("SELECT name FROM sqlite_schema WHERE name = 'openclaw_engine_anchor'").all().length === 1 }; }
      }); opened.push(db); return db;
    };
    try {
      const writer = open(false);
      writer.exec("INSERT INTO items VALUES (1, 'before')");
      const writerPid = writer.prepare('SELECT pg_backend_pid() AS pid').get().pid;
      writer.close();
      const reader = open(true);
      const readerPid = reader.prepare('SELECT pg_backend_pid() AS pid').get().pid;
      assert.notEqual(readerPid, writerPid);
      assert.deepEqual(reader.prepare('SELECT * FROM items').all(), [{ id: 1, value: 'before' }]);
      assert.throws(() => reader.exec("UPDATE items SET value = 'forbidden'"), /read.only/i);
      reader.exec('SET default_transaction_read_only = off');
      assert.throws(() => reader.exec("INSERT INTO items VALUES (2, 'forbidden')"), /read.only/i);
      reader.close();
      const nextWriter = open(false);
      assert.equal(nextWriter.prepare('SELECT pg_backend_pid() AS pid').get().pid, writerPid);
      nextWriter.exec("UPDATE items SET value = 'after'"); nextWriter.close();
      const nextReader = open(true);
      assert.equal(nextReader.prepare('SELECT pg_backend_pid() AS pid').get().pid, readerPid);
      assert.deepEqual(nextReader.prepare('SELECT * FROM items').all(), [{ id: 1, value: 'after' }]);
      assert.throws(() => nextReader.exec('DELETE FROM items'), /read.only/i);
      nextReader.close();
      const cleanup = open(false); const namespace = cleanup.prepare('SELECT current_schema() AS schema').get().schema; cleanup.exec('DROP SCHEMA "'+namespace.replaceAll('"','""')+'" CASCADE');
      return { result: 'PASS', surface: 'built public database-engine-worker-runtime SDK in a real Node worker', writerPid, readerPid, sameRoleReused: true, crossRoleDistinct: true, readerMutationAndDefaultOverrideRejected: true, persistedRows: [{ id: 1, value: 'after' }], schemaRemoved: true };
    } finally { for (const db of opened) db.close(); anchor.close(); }
  });
  parentPort.postMessage(result);
}
```

